fn solve(x: i32) -> i32 {
    // Convert x to string to extract its digit and length
    let s = x.to_string();
    let k = s.len() as i32;                                  // number of repetitions
    let d = s.chars().next().unwrap().to_digit(10).unwrap() as i32;  // the repeated digit

    // For each digit less than d, we have 1+2+3+4 = 10 presses
    // Then for digit d itself, we press lengths 1 through k: sum = k*(k+1)/2
    (d - 1) * 10 + k * (k + 1) / 2
}